const input = Array.isArray($json) ? $json : [$json];
const reviewableJobTypes = ['water heater install', 'water heater replacement', 'repipe', 'sewer line repair', 'sewer line replacement', 'drain cleaning', 'fixture install', 'leak repair'];
return input.map((job) => {
  const jobType = `${job.jobType ?? ''}`.toLowerCase();
  const status = `${job.technicianStatus ?? ''}`.toLowerCase();
  let reviewAction;
  if (job.reviewOptOut === true) {
    reviewAction = 'excluded-review-opt-out';
  } else if (!reviewableJobTypes.some((type) => jobType.includes(type))) {
    reviewAction = 'excluded-job-type';
  } else if (status.includes('unhappy') || status.includes('complaint') || status.includes('manager')) {
    reviewAction = 'manager-follow-up-first';
  } else {
    reviewAction = 'send-review-request';
  }
  return { json: { ...job, reviewAction } };
});
